            unitSize: 1,
            quote: quoteA,
            makerPolicy: FeePolicy.wrap(8888608),
            hooks: hooksA,
            takerPolicy: FeePolicy.wrap(8888708)
        });

        IBookManager.BookKey memory bookKeyB = IBookManager.BookKey({
